<?php
declare(strict_types=1);
namespace Titan\BookingSidecar;
/** Pass 44: assert that persisted Cleanto records match the transaction input. */
final class BookingWriteProofReader { public static function read(\PDO $db,int $id):array {if(BookingPositiveId::parse($id)!==$id||$id>2147483647)throw new \InvalidArgumentException('Invalid proof booking ID');if(!$db->inTransaction())throw new \LogicException('Proof must be inside the booking transaction');$q=$db->prepare('SELECT id,order_id,client_id,order_date,booking_date_time,service_id,method_id,method_unit_id,method_unit_qty,method_unit_qty_rate,booking_status,staff_ids FROM ct_bookings WHERE id=? FOR UPDATE');if($q===false||$q->execute([$id])!==true)throw new \RuntimeException('Booking proof query failed');$booking=$q->fetch(\PDO::FETCH_ASSOC);if(!is_array($booking)||$q->fetch(\PDO::FETCH_ASSOC)!==false)throw new \DomainException('Non-unique or missing booking');$o=$db->prepare('SELECT id,order_id,client_name,client_email,client_phone,client_personal_info,order_duration FROM ct_order_client_info WHERE id=? AND order_id=? FOR UPDATE');if($o===false||$o->execute([$booking['client_id'],$booking['order_id']])!==true)throw new \RuntimeException('Customer order proof query failed');$order=$o->fetch(\PDO::FETCH_ASSOC);if(!is_array($order)||$o->fetch(\PDO::FETCH_ASSOC)!==false)throw new \DomainException('Non-unique or missing customer order');return [$booking,$order];} }
